/** EJECUTA_HI expuesto como endpoint de Actuator: /actuator/bitacorap010. */
@Component
@Endpoint(id = "bitacorap010")
@RequiredArgsConstructor
class BitacoraEndpoint {

    private final BitacoraP010Service servicio;
    private final ArchivoBitacora archivo;
    private final AtomicBoolean monitor = new AtomicBoolean();

    @ReadOperation                                    // HI 1: cifras del proceso
    public Map<String, Object> cifras() {
        return Map.of("fechaProceso", servicio.fechaProceso(),
                      "recibidos", servicio.totRecibidos(),
                      "errores", servicio.totErrores());
        // ALTAS, BAJAS, MODIFICACIONES y CONSULTAS nunca se incrementan en el fuente.
    }

    @WriteOperation                                   // HI 2 / HI 3
    public void monitor(boolean activo) { monitor.set(activo); }

    @WriteOperation                                   // HI 25: cambio de archivo
    public void reabre() {
        archivo.cierra();
        archivo.abreDelDia();                         // INICIA recalcula fecha y título
    }
}
